  $u7=(int)$db->fetch_field($run("SELECT COUNT(DISTINCT metric_users.uid) AS n FROM (SELECT u.uid FROM {$p}users u WHERE u.lastactive >= {$cut7} AND u.uid > 0 AND u.usergroup <> 7{$excludeUsers} UNION SELECT p.uid AS uid FROM {$p}posts p JOIN {$p}users u ON u.uid=p.uid JOIN {$p}threads t ON t.tid=p.tid JOIN {$p}forums f ON f.fid=t.fid JOIN {$p}forumpermissions fp ON fp.fid=f.fid AND fp.gid=1 AND fp.canview=1 AND fp.canviewthreads=1 WHERE p.visible=1 AND t.visible=1 AND f.active=1 AND f.password='' AND p.dateline >= {$cut7} AND p.uid>0 AND u.usergroup<>7{$excludePosts}) metric_users"),'n');
  $u30=(int)$db->fetch_field($run("SELECT COUNT(DISTINCT metric_users.uid) AS n FROM (SELECT u.uid FROM {$p}users u WHERE u.lastactive >= {$cut30} AND u.uid > 0 AND u.usergroup <> 7{$excludeUsers} UNION SELECT p.uid AS uid FROM {$p}posts p JOIN {$p}users u ON u.uid=p.uid JOIN {$p}threads t ON t.tid=p.tid JOIN {$p}forums f ON f.fid=t.fid JOIN {$p}forumpermissions fp ON fp.fid=f.fid AND fp.gid=1 AND fp.canview=1 AND fp.canviewthreads=1 WHERE p.visible=1 AND t.visible=1 AND f.active=1 AND f.password='' AND p.dateline >= {$cut30} AND p.uid>0 AND u.usergroup<>7{$excludePosts}) metric_users"),'n');
