function mybbforums_metric_database_support(string $version):?array{if(stripos($version,'mariadb')!==false){if(!preg_match('/(\d+\.\d+\.\d+)-MariaDB/i',$version,$m)){preg_match_all('/\d+\.\d+\.\d+/',$version,$all);$candidate=end($all[0])?:'';}else$candidate=$m[1];return$candidate!==''&&version_compare($candidate,'10.3.0','>=')?['mariadb','max_statement_time']:null;}if(preg_match('/^(\d+\.\d+\.\d+)/',$version,$m)&&version_compare($m[1],'5.7.8','>='))return['mysql','max_execution_time'];return null;}
